Depth / Code Preference: {artifact_density}
Context:
{context}

Generate structural tutorial output for {domain_name} with scan/build/deep-read support.

QUALITY ENFORCEMENT NOTES (must be applied if present):
{structure_fix_instructions}

Return ONLY JSON with this exact top-level shape:

{{
  "chapter_number": {chapter_number},
  "domain_id": "domain ID from the chapter plan",
  "chapter_title": "Chapter title from the plan",
  "chapter_opener": {{
    "what_this_is_for": "One sentence orientation",
    "when_it_matters": "Specific learning/build moment",
    "failure_looks_like": "Common error symptom or confusion state",
    "produces": ["Concrete output such as file, command result, UI screen, endpoint, test, or deployed artifact"],
    "do_first": ["First action", "Second action"]
  }},
  "minimum_viable_actions": ["3-6 immediate implementation or learning actions"],
  "quick_reference_rules": ["Actionable tutorial rule — Rationale: ... Trigger: ... Risk: ..."],
  "decision_guide": [
    {{
      "decision": "Decision title",
      "if_condition": "Verifiable condition",
      "then_action": "Immediate action",
      "else_action": "Fallback action",
      "escalate_when": "Debugging threshold or review point"
    }}
  ],
  "trigger_blocks": ["Specific event/checkpoint and immediate next response"],
  "risk_blocks": ["Specific mistake or risk and mitigation"],
  "output_summaries": ["Named output and why it matters downstream"],
  "worksheet_linkage": [
    {{
      "worksheet_title": "Exact exercise/checklist title",
      "use_when": "When to use it",
      "unblocks": "What next implementation or learning step it enables"
    }}
  ],
  "cascade_triggers": ["When [specific checkpoint passes], trigger [specific next action] in [named module]"],
  "scenario_scene": "3-5 sentence realistic build/debug/deploy vignette with concrete files, commands, or symptoms",
  "success_metrics": ["3-5 verification outcomes such as passing tests, expected UI states, API responses, logs, or deploy checks"],
  "detailed_explanation": "Deep explanation after structured layers are complete; split into readable units and include examples where useful"
}}
